#pragma once

#include "gui_forms/binding/property_cell/property_cell.hpp"

#include <cstdint>
#include <optional>
#include <string>
#include <utility>

namespace gui_forms {

// LookupComboBox's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/lookup_combo_box.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks), the
// compare and store, then the written hook (the touch, side effects and the
// change event, through the protected virtual on_<property>_changed() where
// Windows Forms has an overridable On<Property>Changed; other properties
// have no hook, and a subclass subscribes to their change events instead). A read is
// `(*control).x.read()`.

// The key of the chosen row, or empty for none. A write of a key no row has throws std::invalid_argument; the field then shows the chosen row's display cell.
template <typename Declaring>
struct LookupComboBoxSelectedKeyCapability {
    PropertyCell<std::string, LookupComboBoxSelectedKeyCapability<Declaring>> selected_key{};

    static void assign(LookupComboBoxSelectedKeyCapability& capability, std::string incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.selected_key), incoming);
        if (!capability.selected_key.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.selected_key));
    }
};

// The column whose cell the field shows for the chosen row. A column the rows lack shows nothing.
template <typename Declaring>
struct LookupComboBoxDisplayColumnCapability {
    PropertyCell<std::uint32_t, LookupComboBoxDisplayColumnCapability<Declaring>> display_column{0U};

    static void assign(LookupComboBoxDisplayColumnCapability& capability, std::uint32_t incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.display_column), incoming);
        if (!capability.display_column.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.display_column));
    }
};

// The rows the open list shows before it scrolls, from 1 to 64 (std::invalid_argument).
template <typename Declaring>
struct LookupComboBoxMaxDropDownRowsCapability {
    PropertyCell<std::uint32_t, LookupComboBoxMaxDropDownRowsCapability<Declaring>> max_drop_down_rows{8U};

    static void assign(LookupComboBoxMaxDropDownRowsCapability& capability, std::uint32_t incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.max_drop_down_rows), incoming);
        if (!capability.max_drop_down_rows.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.max_drop_down_rows));
    }
};

// Every LookupComboBox capability, in the order the declaring class takes them.
template <typename Declaring>
struct LookupComboBoxCapabilities : public LookupComboBoxSelectedKeyCapability<Declaring>,
                                    public LookupComboBoxDisplayColumnCapability<Declaring>,
                                    public LookupComboBoxMaxDropDownRowsCapability<Declaring> {};

} // namespace gui_forms
